package cn.lili.modules.community.p0.stage3;
import cn.lili.modules.community.p0.support.*;import org.junit.jupiter.api.Test;import org.springframework.data.redis.connection.RedisStandaloneConfiguration;import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;import org.springframework.data.redis.core.StringRedisTemplate;import java.nio.file.*;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;
/** Explicitly selected isolated Redis safety test; no Session, database, paid sample or effective credential is created. */
class Stage3LimiterRedisIT {
 @Test void concurrentBudgetAndExpiredWindowAreAtomicAndRunBound()throws Exception{
  Path run=Path.of(Objects.requireNonNull(System.getenv("S3_RUN"))).toRealPath();assertEquals(Path.of("D:/git/daguanglu-p0-stage3/.stage3-runtime").toRealPath(),run.getParent());var owner=object(Files.readString(run.resolve("owner.json")));assertEquals(3,owner.get("stage").getAsInt());var resource=object(Files.readString(run.resolve("runtime/resources.json")));assertEquals(19579,resource.get("redisPort").getAsInt());var secrets=object(Files.readString(run.resolve("private/db.json")));
  var config=new RedisStandaloneConfiguration("127.0.0.1",19579);config.setPassword(secrets.get("redis").getAsString());var factory=new LettuceConnectionFactory(config);factory.afterPropertiesSet();factory.start();var redis=new StringRedisTemplate(factory);redis.afterPropertiesSet();
  String prefix="s3:"+run.getFileName()+":security-test:"+UUID.randomUUID()+":";var keys=List.of(prefix+"actor",prefix+"store",prefix+"ip");var cleanup=new HashSet<String>(keys);
  try{var info=factory.getConnection().serverCommands().info("server");assertEquals(resource.get("redisRunId").getAsString(),info.getProperty("run_id"));var limiter=new Stage3AttemptLimiter(redis);var allowed=new AtomicInteger();var rejected=new AtomicInteger();var tickets=new ConcurrentLinkedQueue<Stage3AttemptLimiter.Ticket>();
   try(var pool=Executors.newFixedThreadPool(16)){var jobs=new ArrayList<Future<?>>();for(int i=0;i<16;i++)jobs.add(pool.submit(()->{try{tickets.add(limiter.begin(keys));allowed.incrementAndGet();}catch(Stage1Exception e){assertEquals(429,e.status());rejected.incrementAndGet();}}));for(var job:jobs)job.get(10,TimeUnit.SECONDS);}
   assertEquals(5,allowed.get());assertEquals(11,rejected.get());assertEquals("5",redis.opsForHash().get(keys.get(0),"count"));var old=tickets.peek();for(String key:keys)redis.expire(key,Duration.ZERO);var fresh=limiter.begin(keys);old.succeeded();assertEquals("1",redis.opsForHash().get(keys.get(0),"count"));fresh.succeeded();assertEquals("0",redis.opsForHash().get(keys.get(0),"count"));
   for(int i=0;i<61;i++){var group=List.of(prefix+"store-actor-"+i,prefix+"same-store",prefix+"same-store-ip");cleanup.addAll(group);if(i<60)assertNotNull(limiter.begin(group));else assertEquals(429,assertThrows(Stage1Exception.class,()->limiter.begin(group)).status());}
   for(int i=0;i<121;i++){var group=List.of(prefix+"ip-actor-"+i,prefix+"ip-store-"+i,prefix+"same-ip");cleanup.addAll(group);if(i<120)assertNotNull(limiter.begin(group));else assertEquals(429,assertThrows(Stage1Exception.class,()->limiter.begin(group)).status());}
  }finally{redis.delete(cleanup);factory.destroy();}
 }
}
